declare(strict_types=1);
require_once __DIR__ . '/../includes/auth.php';$user=require_role('donor');$pdo=db();$impact=donor_impact($pdo,(int)$user['id']);
$badges=$pdo->prepare('SELECT a.*,ua.earned_at FROM achievements a LEFT JOIN user_achievements ua ON ua.achievement_id=a.id AND ua.user_id=? WHERE a.is_active=1 ORDER BY a.target_value');$badges->execute([$user['id']]);$badges=$badges->fetchAll();
$history=$pdo->prepare("SELECT dp.id,dp.updated_at,cr.title,c.organization_name,COALESCE(SUM(di.quantity),0) items FROM donation_pledges dp JOIN clothing_requests cr ON cr.id=dp.request_id JOIN charities c ON c.id=cr.charity_id LEFT JOIN donation_items di ON di.pledge_id=dp.id WHERE dp.donor_id=? AND dp.status='received' GROUP BY dp.id ORDER BY dp.updated_at DESC");$history->execute([$user['id']]);$history=$history->fetchAll();
$pageTitle='Your donor passport';require __DIR__ . '/../includes/header.php'; ?>
