w['items']?> item(s) received by <?=e($row['organization_name'])?></strong><p class="muted" style="margin:5px 0"><?=e($row['title'])?> · <?=format_date($row['updated_at'])?></p><a class="text-link" href="<?=e(url('donor/certificate.php?pledge='.$row['id']))?>">Download donation certificate →</a></article><?php endforeach;?></div><?php endif;?></div><aside class="panel"><div class="panel-heading"><h2>Latest badges</h2><a class="text-link" href="<?=e(url('donor/achievements.php'))?>">All badges →</a></div><?php foreach(array_slice($badges,0,4) as $badge):?><article class="activity-item"><div class="activity-icon"><?=e($badge['icon'])?></div><div><p><strong><?=e($badge['name'])?></strong></p><time><?=$badge['earned_at']?'Earned '.format_date($badge['earned_at']):'In progress'?></time></div></article><?php endforeach;?></aside></div></div></section>
